import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
import { mediaPoster } from './Poster';
import ListEditModal from './ListEditModal';
import { t, text, titleOf } from '../util';
import { updateList, deleteList } from '../api';
import { moved } from '../reorder';

/** One public list. Its owner can drag titles into order, remove them, rename or delete it. */
export default class ListPage extends Page {
  list = null;
  missing = false;
  order = [];
  before = [];
  dragging = null;
  oninit(vnode) {
    super.oninit(vnode);
    app.store.find('shelf-lists', m.route.param('id')).then(list => {
      this.list = list;
      this.order = (list.media() || []).filter(media => !!media);
      app.setTitle(list.name());
      m.redraw();
    }, () => {
      // app.request already showed the alert; the page says the list is gone.
      this.missing = true;
      m.redraw();
    });
  }
  view() {
    if (this.missing) return m("div", {
      className: "container ShelfListPage"
    }, m(Placeholder, {
      text: t('lists.missing')
    }));
    if (!this.list) return m(LoadingIndicator, {
      display: "block"
    });
    const own = !!this.list.user() && app.session.user === this.list.user();
    return m("div", {
      className: "container ShelfListPage"
    }, this.header(this.list, own), this.order.length ? m("ol", {
      className: "ShelfCards ShelfCards--list"
    }, this.order.map((media, index) => this.item(media, index, own))) : m(Placeholder, {
      text: t('lists.empty')
    }));
  }
  header(list, own) {
    const owner = list.user();
    const canDelete = own || app.forum.attribute('canModerateShelf');
    return m("header", {
      className: "ShelfListPage-header"
    }, m("h1", null, list.name()), owner ? m(Link, {
      className: "ShelfListPage-owner",
      href: app.route('user.shelf', {
        username: owner.slug()
      })
    }, m(Avatar, {
      user: owner
    }), " ", username(owner)) : null, list.description() ? m("p", {
      className: "ShelfListPage-description"
    }, list.description()) : null, m("div", {
      className: "ShelfListPage-controls"
    }, own ? m(Button, {
      className: "Button",
      icon: "fas fa-pencil-alt",
      onclick: () => app.modal.show(ListEditModal, {
        list
      })
    }, t('lists.edit_button')) : null, canDelete ? m(Button, {
      className: "Button Button--danger",
      icon: "far fa-trash-alt",
      onclick: () => this.remove()
    }, t('lists.delete_button')) : null), own && this.order.length > 1 ? m("p", {
      className: "ShelfListPage-hint"
    }, t('lists.drag_hint')) : null);
  }
  item(media, index, own) {
    return m("li", {
      key: media.id(),
      className: 'ShelfCard' + (this.dragging === index ? ' is-dragging' : ''),
      draggable: own ? 'true' : undefined,
      ondragstart: own ? e => this.dragStart(e, index) : undefined,
      ondragover: own ? e => this.dragOver(e, index) : undefined,
      ondragend: own ? () => this.dragEnd() : undefined
    }, m("span", {
      className: "ShelfCard-rank"
    }, index + 1), mediaPoster(media, titleOf(media)), m("div", {
      className: "ShelfCard-body"
    }, m("b", {
      className: "ShelfCard-title"
    }, titleOf(media)), own ? m(Button, {
      className: "Button Button--icon Button--link ShelfCard-remove",
      icon: "fas fa-times",
      "aria-label": text('lists.remove_title', {
        title: titleOf(media)
      }),
      onclick: () => this.removeTitle(media)
    }) : null));
  }
  dragStart(e, index) {
    this.dragging = index;
    this.before = this.order.slice();
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', String(index));
    }
  }
  dragOver(e, index) {
    e.preventDefault();
    if (this.dragging === null || this.dragging === index) return;
    this.order = moved(this.order, this.dragging, index);
    this.dragging = index;
  }
  dragEnd() {
    this.dragging = null;
    const ids = this.order.map(media => Number(media.id()));
    if (ids.join() === this.before.map(media => Number(media.id())).join()) return;
    this.save({
      order: ids
    }, this.before);
  }
  removeTitle(media) {
    const before = this.order;
    this.order = this.order.filter(item => item !== media);
    this.save({
      remove: Number(media.id())
    }, before);
  }

  /** Save a change already shown; put the old order back if it fails. */
  save(attributes, before) {
    updateList(this.list, attributes).catch(() => {
      // app.request already showed the alert.
      this.order = before;
      m.redraw();
    });
  }
  remove() {
    const list = this.list;
    if (!confirm(text('lists.delete_confirm', {
      name: list.name()
    }))) return;
    const owner = list.user();
    deleteList(list).then(() => m.route.set(owner ? app.route('user.shelf', {
      username: owner.slug()
    }) : app.route('index')));
  }
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/ListPage', ListPage);